#!/usr/bin/env bash
#
# #241 베타 계정 준비 wizard. 사람이 대화형 터미널에서 실행한다.
# 계정 생성·결제·도메인 구매는 사람이 브라우저에서 직접 한다. 이 스크립트는 안내와 공개 값 기록만 한다.
